/**
 * @param {any} value
 * @returns {number}
 */
export function normalizePositiveCount(value) {
  return Math.max(1, Number(value || 1) | 0);
}

/**
 * @param {string} text
 * @returns {string}
 */
function bracketizeLabel(text) {
  const s = String(text || "");
  if (s.startsWith("[") && s.endsWith("]")) return s;
  return `[${s}]`;
}

/**
 * @param {string} phase
 * @returns {string}
 */
function formatDayPhase(phase) {
  const key = String(phase || '').toLowerCase();
  if (key === 'breakfast') return 'Dawn';
  if (key === 'work') return 'Day';
  if (key === 'pub') return 'Dusk';
  return 'Night';
}

