    }
    const width = Math.max(1, Number(data.width || 1) | 0);
    const tiles = Array.isArray(data.tiles) ? data.tiles : [];
    const cell = minimap.width / width;
    const colors = {
      1: '#8d98a5', 2: '#3b4654', 3: '#b58a58', 4: '#62d3b0', 5: '#6aa7e8',
